<?php require __DIR__.'/includes/header.php';requireAdmin();checkCsrf();if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare('INSERT INTO users(company_id,name,email,password,role,active) VALUES(?,?,?,?,"company_manager",1)')->execute([(int)$_POST['company_id'],$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);$msg='User created';}$rows=db()->query('SELECT u.*,c.name_en company_name FROM users u LEFT JOIN companies c ON c.id=u.company_id ORDER BY u.id DESC')->fetchAll();$companies=db()->query('SELECT id,name_en FROM companies')->fetchAll();?><h1><?=t('users')?></h1><?php if(!empty($msg)):?><div class="alert success"><?=$msg?></div><?php endif;?><section class="card"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" required></label><label><?=t('email')?><input name="email" type="email" required></label><label><?=t('password')?><input name="password" type="password" required></label><label><?=t('company')?><select name="company_id"><?php foreach($companies as $c):?><option value="<?=$c['id']?>"><?=e($c['name_en'])?></option><?php endforeach;?></select></label><div><button class="btn primary">+ <?=t('add')?></button></div></form></section><section class="card table-wrap"><table><thead><tr><th>Name</th><th><?=t('email')?></th><th><?=t('company')?></th><th>Role</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['company_name'])?></td><td><?=e($r['role'])?></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
